const { app, publisher, payments } = makeApp();
const res = await app.handle("POST", "/orders", placeOrderBody());

assert.equal(res.status, 201);
assert.deepEqual(res.body, {
  id: "ord-1",
  status: "placed",
  placedAt: FIXED_NOW,
  currency: "USD",
  totalCents: 1250,
  lines: [{ sku: "SKU-1", name: "Desk lamp", qty: 2, unitPriceCents: 625 }],
});
assert.equal(publisher.events.length, 1);
assert.deepEqual(publisher.events[0], {
  type: "OrderPlaced",
  schemaVersion: 3,
  orderId: "ord-1",
  customerId: "cust-1",
  customerEmail: "jane@example.com",
  placedAt: FIXED_NOW,
  channel: "web",
  currency: "USD",
  totalCents: 1250,
  lines: [{ sku: "SKU-1", qty: 2, unitPriceCents: 625 }],
} satisfies OrderPlaced);
assert.deepEqual(payments.requests, [
  { orderId: "ord-1", customerId: "cust-1", amountMinor: 1250, currency: "USD" },
]);

const [placed, cancelled] = publisher.records;
assert.equal(placed?.topic, "orders.placed");
assert.equal(placed?.key, "ord-1");
assert.equal(placed?.headers["schema-version"], "3");
assert.equal(JSON.parse(placed?.value ?? "{}").totalCents, 1250);
assert.equal(cancelled?.topic, "orders.cancelled");
assert.equal(publisher.drain().length, 2);
